import React, { useState, useRef, useEffect } from 'react';
import { chatPrompts, chatResponses } from '../mock';
import { HelpCircle, Send, X, Minus } from 'lucide-react';

function answer(query) {
  const key = query.trim().toLowerCase();
  if (chatResponses[key]) return chatResponses[key];
  for (const k of Object.keys(chatResponses)) {
    if (k !== 'default' && key.includes(k)) return chatResponses[k];
  }
  return chatResponses.default;
}

export default function PortfolioGuide() {
  const [open, setOpen] = useState(false);
  const [minimized, setMinimized] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState([
    { role: 'bot', text: chatResponses.default },
  ]);
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, open]);

  const send = (text) => {
    if (!text.trim()) return;
    setMessages((m) => [...m, { role: 'user', text }, { role: 'bot', text: answer(text) }]);
    setInput('');
  };

  if (!open) {
    return (
      <button
        onClick={() => { setOpen(true); setMinimized(false); }}
        className="fixed bottom-5 right-5 grad-btn px-5 py-3 text-sm font-medium inline-flex items-center gap-2 z-50"
      >
        <HelpCircle size={16} /> Portfolio guide
      </button>
    );
  }

  return (
    <div className="fixed bottom-5 right-5 z-50 w-[min(380px,calc(100vw-24px))]">
      <div className="glass-card rounded-2xl overflow-hidden shadow-2xl">
        <div className="px-4 py-3 flex items-center justify-between border-b border-black/5"
          style={{ background: 'linear-gradient(135deg,#eef2ff,#f5eaff)' }}>
          <div className="flex items-center gap-2">
            <span className="w-7 h-7 rounded-full grad-btn flex items-center justify-center">
              <HelpCircle size={14} className="text-white" />
            </span>
            <div className="font-serif text-neutral-900">Portfolio guide</div>
          </div>
          <div className="flex items-center gap-1">
            <button onClick={() => setMinimized(!minimized)} className="w-7 h-7 rounded-full hover:bg-white/60 flex items-center justify-center">
              <Minus size={14} />
            </button>
            <button onClick={() => setOpen(false)} className="w-7 h-7 rounded-full hover:bg-white/60 flex items-center justify-center">
              <X size={14} />
            </button>
          </div>
        </div>

        {!minimized && (
          <>
            <div className="px-4 py-3 text-sm text-neutral-700 border-b border-black/5">
              Ask a question or pick a prompt.
            </div>
            <div ref={scrollRef} className="px-4 py-3 max-h-72 overflow-y-auto space-y-2">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div
                    className={`text-[13.5px] leading-relaxed rounded-2xl px-3.5 py-2 max-w-[86%] ${
                      m.role === 'user'
                        ? 'text-white'
                        : 'bg-white text-neutral-800 border border-black/5'
                    }`}
                    style={m.role === 'user' ? { background: 'linear-gradient(135deg,#6d5df6,#4aa9ff)' } : undefined}
                  >
                    {m.text}
                  </div>
                </div>
              ))}
            </div>
            <div className="px-3 pb-3">
              <div className="flex flex-wrap gap-1.5 pb-2">
                {chatPrompts.map((p) => (
                  <button
                    key={p}
                    onClick={() => send(p)}
                    className="text-[12px] px-2.5 py-1 rounded-full border border-violet-200 text-violet-700 bg-violet-50 hover:bg-violet-100"
                  >
                    {p}
                  </button>
                ))}
              </div>
              <form
                onSubmit={(e) => { e.preventDefault(); send(input); }}
                className="flex items-center gap-2 bg-white border border-black/10 rounded-full px-3 py-1.5"
              >
                <input
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Ask a question about Sriprajna's experience"
                  className="flex-1 text-sm outline-none bg-transparent"
                />
                <button type="submit" className="grad-btn w-8 h-8 flex items-center justify-center">
                  <Send size={14} />
                </button>
              </form>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
