import React, { useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { projects } from '../data/projects';
import { ArrowLeft, ExternalLink, CheckCircle2, Target, Briefcase, TrendingUp } from 'lucide-react';
import Navbar from '../components/Navbar';

export default function ProjectDetail() {
  const { slug } = useParams();
  const project = projects[slug];

  useEffect(() => { window.scrollTo(0, 0); }, [slug]);

  if (!project) {
    return (
      <div className="min-h-screen flex items-center justify-center px-6">
        <div className="glass-card rounded-2xl p-10 text-center">
          <h1 className="font-serif text-3xl text-neutral-900">Project not found</h1>
          <p className="text-neutral-600 mt-3">The project you’re looking for doesn’t exist.</p>
          <Link to="/" className="grad-btn inline-flex items-center gap-2 mt-6 px-5 py-2.5 text-sm font-medium">
            <ArrowLeft size={16} /> Back to portfolio
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="relative">
      <Navbar />
      <div className="pt-28 pb-20 px-6 md:px-10">
        <div className="max-w-4xl mx-auto">
          <Link to="/" className="inline-flex items-center gap-2 text-sm text-neutral-600 hover:text-neutral-900">
            <ArrowLeft size={14} /> Back to portfolio
          </Link>

          <div className="mt-6">
            <span className="chip">{project.chip}</span>
            <h1 className="font-serif text-4xl md:text-5xl text-neutral-900 mt-4 leading-tight">{project.title}</h1>
            <p className="text-neutral-600 mt-3 text-[15px]">
              <span className="text-neutral-800 font-medium">Strategy lens:</span> {project.lens}
            </p>
          </div>

          <div className="mt-8 glass-card rounded-2xl p-7">
            <h2 className="font-serif text-2xl text-neutral-900">Overview</h2>
            <p className="text-neutral-700 mt-3 leading-relaxed">{project.overview}</p>
          </div>

          <div className="mt-6 glass-card rounded-2xl p-7">
            <div className="flex items-center gap-2">
              <Target size={18} className="text-violet-600" />
              <h2 className="font-serif text-2xl text-neutral-900">The Problem</h2>
            </div>
            <p className="text-neutral-700 mt-3 leading-relaxed">{project.problem}</p>
          </div>

          <div className="mt-6 glass-card rounded-2xl p-7">
            <div className="flex items-center gap-2">
              <Briefcase size={18} className="text-violet-600" />
              <h2 className="font-serif text-2xl text-neutral-900">My Contribution</h2>
            </div>
            <ul className="mt-4 grid gap-2">
              {project.contribution.map((c, i) => (
                <li key={i} className="flex items-start gap-2 text-neutral-700 leading-relaxed">
                  <CheckCircle2 size={16} className="text-violet-500 mt-1 shrink-0" />
                  <span>{c}</span>
                </li>
              ))}
            </ul>
          </div>

          <div className="mt-6 glass-card rounded-2xl p-7">
            <div className="flex items-center gap-2">
              <TrendingUp size={18} className="text-violet-600" />
              <h2 className="font-serif text-2xl text-neutral-900">Impact &amp; Outcomes</h2>
            </div>
            <ul className="mt-4 grid gap-2">
              {project.impact.map((c, i) => (
                <li key={i} className="flex items-start gap-2 text-neutral-700 leading-relaxed">
                  <CheckCircle2 size={16} className="text-violet-500 mt-1 shrink-0" />
                  <span>{c}</span>
                </li>
              ))}
            </ul>
          </div>

          {project.media && project.media.length > 0 && (
            <div className="mt-6 glass-card rounded-2xl p-7">
              <h2 className="font-serif text-2xl text-neutral-900">Media &amp; References</h2>
              <ul className="mt-4 grid gap-2">
                {project.media.map((m, i) => (
                  <li key={i}>
                    <a href={m.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 text-violet-600 hover:underline text-[15px]">
                      <ExternalLink size={15} /> {m.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          )}

          <div className="mt-10 text-center">
            <Link to="/" className="grad-btn inline-flex items-center gap-2 px-6 py-3 text-sm font-medium">
              <ArrowLeft size={16} /> Back to portfolio
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}
