import React, { useState } from 'react';
import { resources, profile } from '../mock';
import { ArrowUpRight, Mail, X, Download, CheckCircle2 } from 'lucide-react';

export default function Resources() {
  const [modal, setModal] = useState(null); // resource object or null
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const openGate = (r) => { setModal(r); setSubmitted(false); setEmail(''); setName(''); };
  const closeGate = () => setModal(null);

  const submitLead = (e) => {
    e.preventDefault();
    const subject = encodeURIComponent(`Resource request: ${modal.title}`);
    const body = encodeURIComponent(
      `Hi Sriprajna,\n\nI'd like to access the resource: ${modal.title}\n\nName: ${name}\nEmail: ${email}\n\n---\nSent via portfolio resource request.`
    );
    // Optional backend lead capture
    if (process.env.REACT_APP_BACKEND_URL) {
      fetch(`${process.env.REACT_APP_BACKEND_URL}/api/leads`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, email, resource: modal.title }),
      }).catch(() => {});
    }
    window.location.href = `mailto:${profile.email}?subject=${subject}&body=${body}`;
    setSubmitted(true);
  };

  return (
    <section id="resources" className="px-6 md:px-10 py-20">
      <div className="max-w-7xl mx-auto">
        <div className="section-eyebrow">ID Tools &amp; Resources</div>
        <h2 className="font-serif text-4xl md:text-5xl text-neutral-900 mt-3 max-w-3xl leading-tight">
          Tools and resources for learning designers
        </h2>
        <p className="text-neutral-600 mt-5 max-w-3xl leading-relaxed">
          Practical frameworks, templates, and planning tools I created to make instructional design
          work clearer, more consistent, and easier to scale. Request access below and I&rsquo;ll send
          the resource to your inbox.
        </p>

        <div className="mt-8 glass-card rounded-3xl p-7 relative overflow-hidden">
          <div className="absolute top-4 right-6 font-serif text-6xl text-violet-100 select-none">R</div>
          <h3 className="font-serif text-2xl md:text-3xl text-neutral-900 max-w-3xl leading-tight">
            Reusable instructional design resources
          </h3>
          <p className="text-neutral-600 mt-3 max-w-3xl leading-relaxed">
            These resources show how I build systems that support better design decisions, clearer
            stakeholder conversations, and more consistent learning work.{' '}
            <strong className="text-neutral-900">{resources.length} resources.</strong>
          </p>
        </div>

        <div className="mt-6 grid md:grid-cols-2 lg:grid-cols-4 gap-4">
          {resources.map((r) => (
            <article key={r.title} className="glass-card rounded-2xl p-6 hover:-translate-y-1 transition-transform duration-300 flex flex-col">
              <span className="num-badge">{r.letter}</span>
              <h4 className="font-serif text-lg text-neutral-900 mt-4 leading-snug">{r.title}</h4>
              <p className="text-[13px] text-neutral-600 mt-2 leading-relaxed">
                <span className="text-neutral-800 font-medium">Strategy lens:</span> {r.lens}
              </p>
              <p className="text-[14px] text-neutral-700 mt-2 leading-relaxed flex-1">{r.text}</p>
              <div className="mt-4 flex items-center justify-between">
                <span className="chip">{r.chip}</span>
                <button onClick={() => openGate(r)} className="text-sm font-medium text-violet-600 inline-flex items-center gap-1 hover:gap-2 transition-all">
                  Request <ArrowUpRight size={14} />
                </button>
              </div>
            </article>
          ))}
        </div>
      </div>

      {modal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center px-4 bg-black/40 backdrop-blur-sm" onClick={closeGate}>
          <div onClick={(e) => e.stopPropagation()} className="bg-white rounded-2xl w-full max-w-md p-6 shadow-2xl relative">
            <button onClick={closeGate} className="absolute top-3 right-3 w-8 h-8 rounded-full hover:bg-neutral-100 flex items-center justify-center">
              <X size={16} />
            </button>
            {!submitted ? (
              <>
                <div className="w-10 h-10 rounded-full grad-btn flex items-center justify-center">
                  <Download size={16} className="text-white" />
                </div>
                <h3 className="font-serif text-xl text-neutral-900 mt-4 leading-snug">Request access to</h3>
                <p className="font-serif text-2xl text-neutral-900 mt-1">{modal.title}</p>
                <p className="text-sm text-neutral-600 mt-3">
                  Share your name and email &mdash; I&rsquo;ll send this resource directly to your inbox.
                </p>
                <form onSubmit={submitLead} className="mt-5 grid gap-3">
                  <input
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="Your name"
                    className="bg-white border border-black/10 rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-violet-300"
                  />
                  <input
                    required
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="your@email.com"
                    className="bg-white border border-black/10 rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-violet-300"
                  />
                  <button type="submit" className="grad-btn px-5 py-2.5 text-sm font-medium inline-flex items-center justify-center gap-2 mt-1">
                    <Mail size={15} /> Request resource
                  </button>
                  <p className="text-[11.5px] text-neutral-500">
                    Submitting opens your email client prefilled to {profile.email}.
                  </p>
                </form>
              </>
            ) : (
              <div className="text-center py-4">
                <div className="w-14 h-14 rounded-full bg-emerald-100 mx-auto flex items-center justify-center">
                  <CheckCircle2 size={26} className="text-emerald-600" />
                </div>
                <h3 className="font-serif text-2xl text-neutral-900 mt-4">Request sent</h3>
                <p className="text-sm text-neutral-600 mt-2">
                  Your email client should be opening now. I&rsquo;ll respond within 2 business days.
                </p>
                <button onClick={closeGate} className="ghost-btn mt-6 px-5 py-2.5 text-sm font-medium">Close</button>
              </div>
            )}
          </div>
        </div>
      )}
    </section>
  );
}
