import React, { useState } from 'react';
import { profile } from '../mock';
import { Linkedin, Github, Mail, Send, CheckCircle2 } from 'lucide-react';

export default function Contact() {
  const [form, setForm] = useState({ name: '', email: '', message: '' });
  const [sent, setSent] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    const subject = encodeURIComponent(`Portfolio contact from ${form.name || 'Visitor'}`);
    const body = encodeURIComponent(
      `Name: ${form.name}\nEmail: ${form.email}\n\nMessage:\n${form.message}\n\n---\nSent via sriprajna portfolio site.`
    );
    // Try to save to backend if available
    if (process.env.REACT_APP_BACKEND_URL) {
      fetch(`${process.env.REACT_APP_BACKEND_URL}/api/contact`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      }).catch(() => {});
    }
    // Open mailto
    window.location.href = `mailto:${profile.email}?subject=${subject}&body=${body}`;
    setSent(true);
    setTimeout(() => setSent(false), 6000);
  };

  return (
    <section id="contact" className="px-6 md:px-10 py-24">
      <div className="max-w-4xl mx-auto text-center">
        <h2 className="font-serif text-4xl md:text-6xl text-neutral-900 leading-tight">Let&rsquo;s connect</h2>
        <p className="text-neutral-600 mt-5 max-w-2xl mx-auto leading-relaxed">
          I&rsquo;m always interested in thoughtful conversations about technical education, product
          learning, developer content, in-product guidance, and learning strategy for complex
          enterprise products.
        </p>

        <form onSubmit={handleSubmit} className="mt-10 glass-card rounded-2xl p-6 md:p-8 text-left max-w-2xl mx-auto">
          <div className="grid md:grid-cols-2 gap-4">
            <div>
              <label className="text-xs font-medium text-neutral-700 uppercase tracking-wider">Your name</label>
              <input
                required
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                className="mt-1.5 w-full bg-white border border-black/10 rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-violet-300"
                placeholder="Jane Doe"
              />
            </div>
            <div>
              <label className="text-xs font-medium text-neutral-700 uppercase tracking-wider">Email</label>
              <input
                required
                type="email"
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                className="mt-1.5 w-full bg-white border border-black/10 rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-violet-300"
                placeholder="jane@example.com"
              />
            </div>
          </div>
          <div className="mt-4">
            <label className="text-xs font-medium text-neutral-700 uppercase tracking-wider">Message</label>
            <textarea
              required
              rows={4}
              value={form.message}
              onChange={(e) => setForm({ ...form, message: e.target.value })}
              className="mt-1.5 w-full bg-white border border-black/10 rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-violet-300 resize-none"
              placeholder="Tell me what you&rsquo;re working on&hellip;"
            />
          </div>
          <div className="mt-5 flex flex-wrap items-center justify-between gap-3">
            <button type="submit" className="grad-btn px-6 py-3 text-sm font-medium inline-flex items-center gap-2">
              <Send size={15} /> Send message
            </button>
            {sent && (
              <span className="text-sm text-emerald-600 inline-flex items-center gap-1">
                <CheckCircle2 size={15} /> Opening your email client&hellip;
              </span>
            )}
          </div>
          <p className="text-[11.5px] text-neutral-500 mt-3">
            Sending opens your email client prefilled to {profile.email}. No data is stored on this page.
          </p>
        </form>

        <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
          <a href={profile.linkedin} target="_blank" rel="noreferrer" className="grad-btn px-6 py-3 text-sm font-medium inline-flex items-center gap-2">
            <Linkedin size={16} /> Connect on LinkedIn
          </a>
          <a href={profile.github} target="_blank" rel="noreferrer" className="ghost-btn px-6 py-3 text-sm font-medium inline-flex items-center gap-2">
            <Github size={16} /> GitHub Portfolio
          </a>
          <a href={`mailto:${profile.email}`} className="ghost-btn px-6 py-3 text-sm font-medium inline-flex items-center gap-2">
            <Mail size={16} /> {profile.email}
          </a>
        </div>
      </div>

      <footer className="max-w-7xl mx-auto mt-20 pt-8 border-t border-black/10 flex flex-wrap items-center justify-between gap-3 text-sm text-neutral-500">
        <div>&copy; {new Date().getFullYear()} {profile.name}. All rights reserved.</div>
        <div>{profile.location} &middot; Portfolio inspired by editorial design</div>
      </footer>
    </section>
  );
}
