// Scroll-to-section helper compatible with HashRouter
// If already on home ("/"), scroll immediately. If on a subroute
// (e.g., /projects/:slug), navigate home first, then scroll.
export function scrollToSection(id, navigate, pathname) {
  const doScroll = () => {
    const el = document.getElementById(id);
    if (el) {
      const y = el.getBoundingClientRect().top + window.pageYOffset - 64; // offset for fixed navbar
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
  };

  if (pathname !== '/') {
    navigate('/');
    // Wait for home to mount before scrolling
    setTimeout(doScroll, 120);
  } else {
    doScroll();
  }
}
